/** Saves the invoice PDF regenerated by the server (base64) under its file name. */
export function downloadInvoicePdf(input: { filename: string; contentBase64: string }) {
  const binary = atob(input.contentBase64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  const url = URL.createObjectURL(new Blob([bytes], { type: "application/pdf" }));
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = input.filename;
  anchor.style.display = "none";
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  // Safari et iOS lisent parfois le blob bien après le clic : URL gardée 40 s, comme pour le fichier agenda.
  window.setTimeout(() => URL.revokeObjectURL(url), 40_000);
}
